    x1 = x[0]
    x2 = x[1]
    modulated_x1 = np.exp(-0.5 * (x1/2)**2) * np.sin(2 * np.pi * x1)
    return float(0.1 * (modulated_x1 + 0.2 * x2)**2 + (0.5*x2 - 0.1 * modulated_x1)**2 + 0.5 * modulated_x1 * x2 + 0.1 / (1 + np.exp(-x1)))

